import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { spread } from "./src/function/spread.js";
{
function add(a, b) {
    return a + b;
}
function greet(name, greeting = 'Hello') {
    return `${greeting}, ${name}!`;
}
{
{
function greetWithContext(name) {
            return `${this.greeting}, ${name}!`;
        }
        const context = { greeting: 'Hey' };
        const spreadGreetWithContext = spread(greetWithContext.bind(context));
        expect(spreadGreetWithContext(['Alice'])).toBe('Hey, Alice!');
}
}
}
